\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc}
\pagestyle{empty}

% ── Dark-Mode Developer Aesthetic ──
\definecolor{bgdark}{HTML}{0F172A}
\definecolor{bgcard}{HTML}{1E293B}
\definecolor{bgcardalt}{HTML}{1A2332}
\definecolor{bgcardtitle}{HTML}{162032}
\definecolor{bghighlight}{HTML}{172554}
\definecolor{electric}{HTML}{3B82F6}
\definecolor{teal}{HTML}{14B8A6}
\definecolor{amber}{HTML}{F59E0B}
\definecolor{amberlight}{HTML}{FCD34D}
\definecolor{red}{HTML}{EF4444}
\definecolor{textlight}{HTML}{E2E8F0}
\definecolor{textmuted}{HTML}{94A3B8}
\definecolor{textdim}{HTML}{64748B}
\definecolor{bordersub}{HTML}{334155}
\definecolor{electricdim}{HTML}{1E3A5F}
\definecolor{tealdim}{HTML}{134E4A}
\definecolor{amberdim}{HTML}{78350F}
\definecolor{gridline}{HTML}{1E293B}
\definecolor{dotgrid}{HTML}{253349}

\pagecolor{bgdark}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{electric}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{teal}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  electriccard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{electric},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{electric},
    coltitle=electric, colbacktitle=bgcardtitle,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={electric!40},
    colupper=textlight,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=bgcardtitle,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={teal!40},
    colupper=textlight,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgcardtitle,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={amber!40},
    colupper=textlight,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  warncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberdim!50!bgdark,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=amberdim!70!bgdark,
    toptitle=6pt, bottomtitle=6pt,
    colupper=textlight,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bghighlight,
    borderline west={5pt}{0pt}{electric},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=electric!80!bgdark,
    toptitle=6pt, bottomtitle=6pt,
    colupper=textlight,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
}

\begin{document}

% ── Dot grid background ──
\begin{tikzpicture}[remember picture, overlay]
  \foreach \x in {0,8,...,594} {
    \foreach \y in {0,8,...,841} {
      \fill[dotgrid] (\x mm, \y mm) circle (0.3mm);
    }
  }
\end{tikzpicture}

\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════
% TITLE BAR — rows top to row3
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, colframe=bgdark, colupper=white,
  arc=0pt, boxrule=0pt,
  borderline south={2pt}{0pt}{electric!60},
  left=30pt, right=30pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{22}{26}\selectfont\color{electric}\texttt{github.com/nickmessing/js-framework-benchmark}}\\[8pt]
  {\fontsize{60}{72}\selectfont\bfseries\color{white} JS Framework Benchmark}\\[6pt]
  {\fontsize{28}{34}\selectfont\color{textmuted} 5 Years of Browser Performance Testing\enspace\textbar\enspace Chrome 55\,--\,146\enspace\textbar\enspace 2017\,--\,2026}
}

% ══════════════════════════════════════════════
% HERO STATS BANNER — rows row3 to row6
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={1.5pt}{0pt}{bordersub},
]{name=stats, column=1, span=3, between=row3 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{electric!50}{electricdim!60!bgdark}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{electric} 60+}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} Official Benchmark Runs}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textdim} Chrome 55\,--\,146}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{teal!50}{tealdim!60!bgdark}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{teal} 8}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} Years of Tracking}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textdim} 2017\,--\,2026}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{amber!50}{amberdim!60!bgdark}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{amber} 95\%+}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} Runs on macOS}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textdim} Only 2 Windows runs}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════
% COLUMN 1: Overview + Timeline Table
% ══════════════════════════════════════════════

% ── What Is the JS Framework Benchmark? ──
\posterbox[electriccard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row6 and row10}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Most widely referenced open-source JS framework benchmark
    \item Measures real DOM operations: create 1K rows, partial updates, selection, swap, removal, startup
    \item Runs in real Chrome with controlled CPU throttling
    \item Maintained by Stefan Krause; covers keyed \& non-keyed implementations
  \end{itemize}
  \vspace{8pt}
  \colorbox{electricdim!50!bgdark}{\parbox{0.93\linewidth}{\centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{electric} Consistent yardstick for framework performance across 60+ data points}%
    \vspace{4pt}}}
}

% ── Official Runs by Year ──
\posterbox[tealcard, title={Official Runs by Year}
]{name=runstable, column=1, between=row10 and row16}{
  \fontsize{20}{28}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}p{32mm}p{68mm}cp{50mm}@{}}
    \rowcolor{teal!15!bgcard}
    {\bfseries\color{teal}Year} & {\bfseries\color{teal}Chrome Versions} & {\bfseries\color{teal}Runs} & {\bfseries\color{teal}Notes} \\
    \rowcolor{bgcardalt}
    2017--19 & 55, 58, 62, 69 & 4 & Early era \\
    \rowcolor{bgcard}
    2020 & 83\,--\,87 & 5 & GitHub Pages \\
    \rowcolor{bgcardalt}
    2021 & 88\,--\,96 & 9 & Monthly cadence \\
    \rowcolor{bgcard}
    2022 & 97\,--\,108 & 13 & +\,2 Windows runs \\
    \rowcolor{bgcardalt}
    \color{amber}2023 & \color{amber}109\,--\,120 & \color{amber}12 & \color{amber}Methodology overhaul \\
    \rowcolor{bgcard}
    2024 & 121\,--\,131 & 12 & +\,1 Windows run \\
    \rowcolor{bgcardalt}
    2025 & 132\,--\,143 & 12 & Most active year \\
    \rowcolor{bgcard}
    2026 & 144\,--\,146 & 3 & Latest: Chrome 146 \\
  \end{tabular}
}

% ── Platform Coverage ──
\posterbox[ambercard, title={Platform Coverage}
]{name=platform, column=1, between=row16 and row20}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{macOS (OSX)} $\to$ 95\%+ of all runs
    \item \textbf{Windows} $\to$ only Chrome 104 (2022) and Chrome 121 (2024)
    \item Results reflect macOS + Chrome performance characteristics
  \end{itemize}
  \vspace{8pt}
  \colorbox{amberdim!50!bgdark}{\parbox{0.93\linewidth}{\centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{amber} Cross-platform extrapolation is not recommended}%
    \vspace{4pt}}}
}

% ══════════════════════════════════════════════
% COLUMN 2: Timeline (centerpiece)
% ══════════════════════════════════════════════

% ── Timeline: Chrome 55 → 146 ──
\posterbox[
  enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
  borderline west={4pt}{0pt}{electric},
  left=14pt, right=12pt, top=4pt, bottom=4pt,
  fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{electric},
  coltitle=electric, colbacktitle=bgcardtitle,
  toptitle=6pt, bottomtitle=6pt,
  titlerule=1.5pt, titlerule style={electric!40},
  colupper=textlight,
  valign=top, drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  title={Benchmark Timeline: Chrome 55\,\textrightarrow\,146}
]{name=timeline, column=2, between=row6 and row20}{
  \fontsize{20}{26}\selectfont
  \begin{tikzpicture}[x=1mm, y=1mm]
    % Timeline vertical line
    \draw[electric!60, line width=2pt] (10,0) -- (10,-340);

    % ── 2017-2019 ──
    \fill[electric] (10,-5) circle (3mm);
    \node[right, text width=120mm] at (18,-5) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{electric} 2017--2019}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 55, 58, 62, 69 \textbar\ 4 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Early era on stefankrause.net}
    };

    % ── 2020 ──
    \fill[electric] (10,-55) circle (3mm);
    \node[right, text width=120mm] at (18,-55) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{electric} 2020}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 83\,--\,87 \textbar\ 5 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Migrated to GitHub Pages}
    };

    % ── 2021 ──
    \fill[teal] (10,-100) circle (3mm);
    \node[right, text width=120mm] at (18,-100) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{teal} 2021}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 88\,--\,96 \textbar\ 9 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Steady monthly cadence established}
    };

    % ── 2022 ──
    \fill[teal] (10,-145) circle (3mm);
    \node[right, text width=120mm] at (18,-145) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{teal} 2022}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 97\,--\,108 \textbar\ 13 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Peak frequency + 2 Windows runs}
    };

    % ── CHROME 118 CALLOUT ──
    \draw[amber, line width=2.5pt] (10,-190) -- (10,-230);
    \fill[amber] (10,-210) circle (4mm);
    \draw[amber, line width=1.5pt, dashed] (18,-195) rectangle (155,-245);
    \fill[amberdim!60!bgdark] (19,-196) rectangle (154,-244);
    \node[right, text width=128mm] at (22,-205) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{amber} \raisebox{1pt}{$\triangle$}\ \ CHROME 118 --- METHODOLOGY OVERHAUL}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{amberlight} Switched to weighted geometric mean}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{amberlight} CPU throttling factors recalibrated}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{amber} Cross-version comparisons break here}
    };

    % ── 2023 label ──
    \node[left, text width=40mm, align=right] at (4,-210) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{amber} 2023}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} 12 runs}
    };

    % ── 2024 ──
    \fill[electric] (10,-265) circle (3mm);
    \node[right, text width=120mm] at (18,-265) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{electric} 2024}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 121\,--\,131 \textbar\ 12 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Includes 1 Windows run (Chrome 121)}
    };

    % ── 2025 ──
    \fill[teal] (10,-310) circle (3mm);
    \node[right, text width=120mm] at (18,-310) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{teal} 2025}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 132\,--\,143 \textbar\ 12 runs}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textdim} Most active year; alternating keyed-only}
    };

    % ── 2026 ──
    \fill[electric] (10,-340) circle (2.5mm);
    \draw[electric, line width=1pt] (10,-340) circle (5mm);
    \node[right, text width=120mm] at (18,-338) {%
      {\fontsize{22}{28}\selectfont\bfseries\color{electric} 2026}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Chrome 144\,--\,146 \textbar\ 3 runs (so far)}
    };
  \end{tikzpicture}
}

% ══════════════════════════════════════════════
% COLUMN 3: Methodology + Takeaways
% ══════════════════════════════════════════════

% ── Methodology Milestones ──
\posterbox[warncard, title={\raisebox{1pt}{$\triangle$}\ \ Methodology Milestones}
]{name=methodology, column=3, between=row6 and row12}{
  \fontsize{22}{30}\selectfont

  \colorbox{amberdim!40!bgdark}{\parbox{0.93\linewidth}{\vspace{5pt}%
    {\fontsize{20}{26}\selectfont\color{amber}\bfseries Chrome 118 (2023)}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textlight} Arithmetic mean $\to$ weighted geometric mean\\
    CPU throttling factors recalibrated}\vspace{5pt}%
  }}
  \vspace{10pt}

  \colorbox{amberdim!40!bgdark}{\parbox{0.93\linewidth}{\vspace{5pt}%
    {\fontsize{20}{26}\selectfont\color{amber}\bfseries Chrome 118+ (2023--present)}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textlight} Ongoing timing and driver refinements}\vspace{5pt}%
  }}
  \vspace{10pt}

  \colorbox{amberdim!40!bgdark}{\parbox{0.93\linewidth}{\vspace{5pt}%
    {\fontsize{20}{26}\selectfont\color{amber}\bfseries Chrome 139+ (2025--2026)}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textlight} Odd versions $\to$ keyed frameworks only\\
    Even versions $\to$ keyed + non-keyed}\vspace{5pt}%
  }}

  \vspace{12pt}
  \fcolorbox{red!60}{red!15!bgdark}{\parbox{0.90\linewidth}{\centering\vspace{5pt}%
    {\fontsize{20}{26}\selectfont\bfseries\color{red} Comparisons across Chrome versions are not always safe}%
    \vspace{5pt}}}
}

% ── Keyed vs Non-Keyed ──
\posterbox[tealcard, title={Keyed vs Non-Keyed}
]{name=keyed, column=3, between=row12 and row15}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Keyed:} each DOM node permanently associated with its data item
    \item \textbf{Non-keyed:} DOM nodes may be recycled across data items
    \item Since Chrome 139, odd versions benchmark keyed only
  \end{itemize}
}

% ── Key Takeaways ──
\posterbox[highlightcard, title={Key Takeaways for Developers}
]{name=takeaways, column=3, between=row15 and row20}{
  \fontsize{22}{30}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Compare within the same Chrome version} --- methodology differs across releases
    \item \textbf{Consult Chrome 146} for current framework standings
    \item \textbf{Understand keyed vs non-keyed} --- recent odd versions are keyed-only
    \item \textbf{Weighted geometric mean} (since Chrome 118) provides a more balanced score
    \item \textbf{8 years, 60+ data points} --- the most comprehensive JS perf tracker
  \end{enumerate}
}

\end{tcbposter}
\end{document}

