tsize{18}{24}\\selectfont\\color{textmuted} Chrome 97\\,--\\,108 \\textbar\\ 13 runs}\\\\[2pt]\n      {\\fontsize{17}{22}\\selectfont\\color{textdim} Peak frequency + 2 Windows runs}\n    };\n\n    % ── CHROME 118 CALLOUT ──\n    \\draw[amber, line width=2.5pt] (10,-190) -- (10,-230);\n    \\fill[amber] (10,-210) circle (4mm);\n    \\draw[amber, line width=1.5pt, dashed] (18,-195) rectangle (155,-245);\n    \\fill[amberdim!60!bgdark] (19,-196) rectangle (154,-244);\n    \\node[right, text width=128mm] at (22,-205) {%\n      {\\fontsize{22}{28}\\selectfont\\bfseries\\color{amber} \\raisebox{1pt}{$\\triangle$}\\ \\ CHROME 118 --- METHODOLOGY OVERHAUL}\\\\[4pt]\n      {\\fontsize{18}{24}\\selectfont\\color{amberlight} Switched to weighted geometric mean}\\\\[2pt]\n      {\\fontsize{18}{24}\\selectfont\\color{amberlight} CPU throttling factors recalibrated}\\\\[2pt]\n      {\\fontsize{17}{22}\\selectfont\\color{amber} Cross-version comparisons break here}\n    };\n\n    % ── 2023 label ──\n    \\node[left, text width=40mm, align=right] at (4,-210) {%\n      {\\fontsize{22}{28}\\selectfont\\bfseries\\color{amber} 2023}\\\\[2pt]\n      {\\fontsize{18}{24}\\selectfont\\color{textmuted} 12 runs}\n    };\n\n    % ── 2024 ──\n    \\fill[electric] (10,-265) circle (3mm);\n    \\node[right, text width=120mm] at (18,-265) {%\n      {\\fontsize{22}{28}\\selectfont\\bfseries\\color{electric} 2024}\\\\[2pt]\n      {\\fontsize{18}{24}\\selectfont\\color{textmuted} Chrome 121\\,--\\,131 \\textbar\\ 12 runs}\\\\[2pt]\n      {\\fontsize{17}{22}\\selectfont\\color{textdim} Includes 1 Windows run (Chrome 121)}\n    };\n\n    % ── 2025 ──\n    \\fill[teal] (10,-310) circle (3mm);\n    \\node[right, text width=120mm] at (18,-310) {%\n      {\\fontsize{22}{28}\\selectfont\\bfseries\\color{teal} 2025}\\\\[2pt]\n      {\\fontsize{18}{24}\\selectfont\\color{textmuted} Chrome 132\\,--\\,143 \\textbar\\ 12 runs}\\\\[2pt]\n      {\\fontsize{17}{22}\\selectfont\\color{textdim} Most active year; alternating keyed-only}\n    };\n\n    % ── 2026 ──\n    \\fill[electric] (10,-340) circle (2.5mm);\n    \\draw[electric, line width=1pt] (10,-340) circle (5mm);\n    \\node[right, text width=120mm] at (18,-338) {%\n      {\\fontsize{22}{28}\\selectfont\\bfseries\\color{electric} 2026}\\\\[2pt]\n      {\\fontsize{18}{24}\\selectfont\\color{textmuted} Chrome 144\\,--\\,146 \\textbar\\ 3 runs (so far)}\n    };\n  \\end{tikzpicture}\n}\n\n% ══════════════════════════════════════════════\n% COLUMN 3: Methodology + Takeaways\n% ══════════════════════════════════════════════\n\n% ── Methodology Milestones ──\n\\posterbox[warncard, title={\\raisebox{1pt}{$\\triangle$}\\ \\ Methodology Milestones}\n]{name=methodology, column=3, between=row6 and row12}{\n  \\fontsize{22}{30}\\selectfont\n\n  \\colorbox{amberdim!40!bgdark}{\\parbox{0.93\\linewidth}{\\vspace{5pt}%\n    {\\fontsize{20}{26}\\selectfont\\color{amber}\\bfseries Chrome 118 (2023)}\\\\[3pt]\n    {\\fontsize{20}{26}\\selectfont\\color{textlight} Arithmetic mean $\\to$ weighted geometric mean\\\\\n    CPU throttling factors recalibrated}\\vspace{5pt}%\n  }}\n  \\vspace{10pt}\n\n  \\colorbox{amberdim!40!bgdark}{\\parbox{0.93\\linewidth}{\\vspace{5pt}%\n    {\\fontsize{20}{26}\\selectfont\\color{amber}\\bfseries Chrome 118+ (2023--present)}\\\\[3pt]\n    {\\fontsize{20}{26}\\selectfont\\color{textlight} Ongoing timing and driver refinements}\\vspace{5pt}%\n  }}\n  \\vspace{10pt}\n\n  \\colorbox{amberdim!40!bgdark}{\\parbox{0.93\\linewidth}{\\vspace{5pt}%\n    {\\fontsize{20}{26}\\selectfont\\color{amber}\\bfseries Chrome 139+ (2025--2026)}\\\\[3pt]\n    {\\fontsize{20}{26}\\selectfont\\color{textlight} Odd versions $\\to$ keyed frameworks only\\\\\n    Even versions $\\to$ keyed + non-keyed}\\vspace{5pt}%\n  }}\n\n  \\vspace{12pt}\n  \\fcolorbox{red!60}{red!15!bgdark}{\\parbox{0.90\\linewidth}{\\centering\\vspace{5pt}%\n    {\\fontsize{20}{26}\\selectfont\\bfseries\\color{red} Comparisons across Chrome versions are not always safe}%\n    \\vspace{5pt}}}\n}\n\n% ── Keyed vs Non-Keyed ──\n\\posterbox[tealcard, title={Keyed vs Non-Keyed}\n]{name=keyed, column=3, between=row12 and row15}{\n  \\fontsize{24}{32}\\selectfont\n  \\begin{itemize}[itemsep=10pt]\n    \\item \\textbf{Keyed:} each DOM node permanently associated with its data item\n    \\item \\textbf{Non-keyed:} DOM nodes may be recycled across data items\n    \\item Since Chrome 139, odd versions benchmark keyed only\n  \\end{itemize}\n}\n\n% ── Key Takeaways ──\n\\posterbox[highlightcard, title={Key Takeaways for Developers}\n]{name=takeaways, column=3, between=row15 and row20}{\n  \\fontsize{22}{30}\\selectfont\n  \\begin{enumerate}[itemsep=10pt]\n    \\item \\textbf{Compare within the same Chrome version} --- methodology differs across releases\n    \\item \\textbf{Consult Chrome 146} for current framework standings\n    \\item \\textbf{Understand keyed vs non-keyed} --- recent odd versions are keyed-only\n    \\item \\textbf{Weighted geometric mean} (since Chrome 118) provides a more balanced score\n    \\item \\textbf{8 years, 60+ data points} --- the most comprehensive JS perf tracker\n  \\end{enumerate}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 390, "startLine": 1, "totalLines": 390}}

