  label={\color{electric}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{teal}\bfseries\arabic*.}}

% ── Card styles (no shadow xshift/yshift) ──
\tcbset{
  electriccard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{electric},
