\posterbox[tealcard, title={Keyed vs Non-Keyed}
]{name=keyed, column=3, between=row11 and row14}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Keyed:} DOM node permanently tied to its data item
    \item \textbf{Non-keyed:} DOM nodes may be recycled across data items
    \item Since Chrome 139, odd versions benchmark keyed only
  \end{itemize}
}

\posterbox[highlightcard, title={Key Takeaways for Developers}
]{name=takeaways, column=3, between=row14 and row20}{
  \fontsize{22}{30}\selectfont
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{Compare within one Chrome version} --- methodology and throttling differ across releases
    \item \textbf{Consult Chrome 146} for the most up-to-date framework standings
    \item \textbf{Understand keyed vs non-keyed} --- recent odd Chrome versions are keyed-only
    \item \textbf{Weighted geometric mean} since Chrome 118 gives a more balanced overall score
    \item \textbf{60+ runs over 8 years} --- the longest-running, most comprehensive JS perf tracker available
  \end{enumerate}
}

